SELECT match_id, match_date, venue, city, stage
FROM Matches
WHERE season = '2022' AND toss_winner = 'MI' AND toss_decision = 'bat';

SELECT city, GROUP_CONCAT(DISTINCT venue) AS stadiums
FROM Matches
GROUP BY city;

SELECT DISTINCT city, venue 
FROM Matches 
WHERE city IS NOT NULL AND venue IS NOT NULL;

SELECT DISTINCT city, venue 
FROM Matches 
ORDER BY city, venue;

SELECT DISTINCT city, venue 
FROM Matches 
ORDER BY city, venue;

SELECT COUNT(*) AS match_count
FROM Matches
WHERE venue = 'Dharamsala';

SELECT MAX(extra_runs) AS max_extra_runs
FROM Deliveries
WHERE bowling_team = 'CSK';
